// Simple in-memory store standing in for a real database.
const store = { notificationsEnabled: false }

export async function getNotificationPreference(): Promise<boolean> {
  return store.notificationsEnabled
}

export async function setNotificationPreference(enabled: boolean): Promise<void> {
  store.notificationsEnabled = enabled
}

